\label{def:profile}
Let $\tau$ be a $G$-torsor over a field $F\supseteq k$ and $d\ge1$. Put
\begin{gather*}
\operatorname{ed}^{[d]}_k(\tau):=\min\{\operatorname{ed}_k(\tau\otimes_FF')\;:\;F'/F\text{ a field extension},\ [F':F]\le d\},\\
d_j(\tau):=\min\{d\ge1:\operatorname{ed}^{[d]}_k(\tau)\le j\}\qquad(0\le j\le\operatorname{ed}_k(\tau)).
\end{gather*}
The sequence $(\operatorname{ed}^{[d]}_k(\tau))_{d\ge1}$ is the \emph{finite-degree profile} of $\tau$ and the $d_j(\tau)$ are its \emph{jump degrees}; they depend on $k$, and when the base field varies we write $d_{j,k}(\tau)$. For a prime $q$ we also write $\operatorname{ed}^{[d]}_k{}'(\tau):=\min\{\operatorname{ed}_k(\tau\otimes F'):[F':F]\le d,\ q\nmid[F':F]\}$, the \emph{prime-to-$q$ profile}, so that $\operatorname{ed}^{[d]}_k\le\operatorname{ed}^{[d]}_k{}'$, and $d_j^{(q')}(\tau):=\min\{d:\operatorname{ed}^{[d]}_k{}'(\tau)\le j\}$ ($=\infty$ if no such $d$ exists), the \emph{prime-to-$q$ jump degrees}: $d_j^{(q')}(\tau)$ is the least degree prime to $q$ of an extension over which $\tau$ needs at most $j$ parameters. (The minimum of $d$ prime to $q$ with $\operatorname{ed}^{[d]}_k(\tau)\le j$ would be a different and uninformative number, since $\operatorname{ed}^{[d]}_k$ minimises over all extensions of degree $\le d$, including those of degree divisible by $q$.)

\label{thm:geom}
Let $G$ be a finite group, $k$ any field, $\tau\colon T\to\operatorname{Spec} F$ a $G$-torsor, $F\supseteq k$, and $m,d\ge0$. The following are equivalent:
\begin{enumerate}[label=\textup{(\arabic*)}]
\item $\operatorname{ed}^{[d]}_k(\tau)\le m$;
\item there is a quasi-projective generically free primitive $G$-variety $Z$ over $k$ with $\dim Z\le m$ such that ${}^{\tau}\!Z$ has a closed point of degree $\le d$ in the free locus ${}^{\tau}\!(Z^{\mathrm{free}})$;
\item there are $Z$ as in \textup{(2)} and a field $F'/F$ with $[F':F]\le d$ such that ${}^{\tau\otimes F'}\!Z$ has a free $F'$-point, i.e.\ a $G$-equivariant morphism $T\times_FF'\to Z^{\mathrm{free}}$.
\end{enumerate}
For $\tau=\tau_{\mathrm{gen}}$ (generic torsor of $V$), \textup{(3)} says: there is a $G$-equivariant rational map $W'\dashrightarrow Z^{\mathrm{free}}$ from the normalisation $W'$ of $V$ in $L\otimes_KF'$, a (possibly reducible) $G$-variety dominating $V$ with degree $[F':K]\le d$; when $L\otimes_KF'$ is a field this is a $G$-equivariant correspondence $V\rightsquigarrow Z$ of degree $\le d$ in the sense of \cite[(2.6)]{RS22} landing in $Z^{\mathrm{free}}$, and $Z$ can then be taken irreducible with faithful $G$-action. In particular, by (2), $d_j(\tau)$ is the least degree of a closed point in the free locus of ${}^{\tau}\!Z$ over all such $Z$ with $\dim Z\le j$.

\label{prop:qgp}
Let $G$ be a $q$-group of order $q^n$, $\operatorname{char}k\ne q$ ($k$ perfect if positive), $c=[k(\mu_q):k]$. Then:
\begin{enumerate}[label=\textup{(\alph*)}]
\item $\operatorname{ed}^{[d]}_k(\tau_{\mathrm{gen}})=\operatorname{ed}_{k,q}(G)$ for $c\le d\le q-1$, and $\operatorname{ed}_{k,q}(G)\le\operatorname{ed}^{[d]}_k(\tau_{\mathrm{gen}})\le\operatorname{ed}_k(G)$ for $d<c$;
\item $\operatorname{ed}_{k,q}(G)=\operatorname{ed}_{k(\mu_q)}(G)$, and this is the minimal dimension of a faithful $k(\mu_q)$-representation of $G$;
\item $q\mid d_j(\tau_{\mathrm{gen}})$ for every $j<\operatorname{ed}_{k,q}(G)$, and $d_0(\tau_{\mathrm{gen}})=q^n$;
\item if $\mu_q\subset k$: $\operatorname{ed}^{[d]}_k(\tau_{\mathrm{gen}})=\operatorname{ed}_k(G)$ for $d<q$ and all steps of the profile occur at multiples of $q$, i.e.\ $\operatorname{ed}^{[d]}_k(\tau_{\mathrm{gen}})=\operatorname{ed}^{[q\lfloor d/q\rfloor]}_k(\tau_{\mathrm{gen}})$ for $d\ge q$.
\end{enumerate}

\label{lem:flag}
Assume $k$ is algebraically closed, let $\Omega$ be an algebraic closure of $L$ (so $\Omega$ is algebraic over $K$ and contains, after an embedding over $K$, every finite extension $F'$ of $K$), and let $A\le G$ be abelian with $\operatorname{char}k\nmid|A|$. Then there is a valuation $\nu$ on $\Omega$, trivial on $k$, such that
\begin{enumerate}[label=\textup{(\roman*)}]
\item $\kappa(M)=k$ for every field $k\subseteq M\subseteq\Omega$;
\item $A\subseteq\varphi(\mathrm{Dec}_K)$.
\end{enumerate}

\label{thm:rankindex}
Let $k$ be any field, $G$ a finite group, $V$ a faithful representation of $G$ over $k$ with generic torsor $\tau_{\mathrm{gen}}$ over $K$, and $A\le G$ an abelian subgroup with $\operatorname{char}k\nmid|A|$.
\begin{enumerate}[label=\textup{(\alph*)}]
\item For every finite field extension $F'/K$, $\operatorname{ed}_k(\tau_{\mathrm{gen}}\otimes_KF')\ge\rho_A([F':K]_s)$.
\item For every $d\ge1$, $\operatorname{ed}^{[d]}_k(\tau_{\mathrm{gen}})\ge\rho_A(d)$. Equivalently, $d_j(\tau_{\mathrm{gen}})\ge\min\{[A:B]:\ B\le A,\ \operatorname{rk} B\le j\}$ for $0\le j\le\operatorname{ed}_k(\tau_{\mathrm{gen}})$.
\end{enumerate}

\label{prop:A4}
Assume $k$ is algebraically closed; let $A$ and $\nu$ be as in Lemma~\ref{lem:flag}. Let $F'\supseteq K$ be a field inside $\Omega$, finite over $K$ with $[F':K]_s\le d$, and $k\subseteq E\subseteq F'$ a subfield with $\tau_{\mathrm{gen}}\otimes_KF'\cong\tau_0\otimes_EF'$ for a $G$-torsor $\tau_0$ over $E$ classified by $\psi\colon\Gamma_E\to G$. Then there is $h\in G$ such that $B':=A\cap\varphi(\mathrm{Dec}_{F'})$ satisfies
\begin{enumerate}[label=\textup{(\alph*)}]
\item $[A:B']\le d$;
\item $h^{-1}B'h\subseteq\psi(\mathrm{Dec}_E)$.
\end{enumerate}

\label{rem:limits}
(i) Theorem~\ref{thm:rankindex} says nothing beyond $d_0$ for cyclic groups. Every abelian subgroup $A$ of a cyclic group is cyclic, and for $d<|A|$ every $B\le A$ of index $\le d$ is non-trivial, so $\rho_A(d)=1$; the theorem gives only $\operatorname{ed}^{[d]}_k(\tau_{\mathrm{gen}})\ge1$ for $d<|A|$. This is why the computation of $d_1(\tau_{\mathrm{gen}}(\mathbb{Z}/p))$ in Section~\ref{sec:thmB} needs a different, curve-theoretic method, and why the first open case of the subgroup formula \eqref{eq:subgroupformula} is cyclic.
(ii) Even at $d=1$ the bound $\max_A\rho_A(1)=\max_A\operatorname{rk} A$ can be smaller than $\operatorname{ed}_k(G)$ for non-abelian $G$. For the quaternion group $Q_8$ and $k=\mathbb C$ every abelian subgroup is cyclic, so the theorem gives $\operatorname{ed}_{\mathbb C}(Q_8)\ge1$ only, while $\operatorname{ed}_{\mathbb C}(Q_8)=\operatorname{rdim}_{\mathbb C}(Q_8)=2$ by Theorem~\ref{thm:KM}: $Q_8$ is non-abelian, so it has no faithful one-dimensional representation, and its two-dimensional irreducible representation is faithful.

\label{rem:checksB}
(i) For $d=1$ (so $m_0=1$, $d''=1$) Steps~1--10 give $r\le2$, hence $m\le2$ and $c\in k$ by Lemma~\ref{lem:cyclo}: if $\operatorname{ed}_k(\mathbb{Z}/p)=1$ then $\zeta+\zeta^{-1}\in k$. With Lemma~\ref{lem:B1} this is the criterion $\operatorname{ed}_k(\mathbb{Z}/p)=1\iff\zeta+\zeta^{-1}\in k$ in characteristic $0$.
(ii) Over $\mathbb{Q}$: for $p=3$, $c=-1\in\mathbb{Q}$ and $d_{1,\mathbb{Q}}(\tau_{\mathrm{gen}})=1$, i.e.\ $\operatorname{ed}_\mathbb{Q}(\mathbb{Z}/3)=1$. For $p=5$, $d_{1,\mathbb{Q}}(\tau_{\mathrm{gen}})=2$: thus $\operatorname{ed}_\mathbb{Q}(\mathbb{Z}/5)\ge2$, and the profile drops to $1$ at degree $2$. For $p=7$, $d_{1,\mathbb{Q}}(\tau_{\mathrm{gen}})=3$. The role of the constant field $k_0$ is visible at $p=7$: for $F'=K(\sqrt{-7})=Kk_0$ with $k_0=\mathbb{Q}(\sqrt{-7})$ one has $d=2$, $m_0=2$, and Step~10 would require $[k_0(\zeta_7):k_0]=3\le2d/m_0=2$; so $\operatorname{ed}_\mathbb{Q}(\tau_{\mathrm{gen}}\otimes K(\sqrt{-7}))\ge2$.
